select 
from lab_device d
where d.del_flag = '0'


    and d.laboratory_id = #{laboratoryId}


    and d.category_code = #{categoryCode}


    and d.status = #{status}


    and (d.asset_no like concat('%', #{keyword}, '%')
        or d.name like concat('%', #{keyword}, '%')
        or d.model like concat('%', #{keyword}, '%')
        or d.location like concat('%', #{keyword}, '%'))



        order by ${sort.column} ${sort.direction}


        order by d.create_time desc

